export default async (ctx, client) => {
  const t = await client.operations.execute({
    connection_id: 432, operation_key: 'get_accessibility_tree',
    input: { tab_id: 558570442, filter: 'all' },
  });
  const out = t.output;
  const nodes = out.nodes || out.tree || out;
  const flat = JSON.stringify(nodes);
  // find candidate nodes by exact name
  const collect = (n, acc=[]) => {
    if (!n || typeof n !== 'object') return acc;
    if (Array.isArray(n)) { n.forEach(x=>collect(x,acc)); return acc; }
    const name = (n.name||'').trim().toLowerCase();
    if (name === 'message' || name === 'send message') acc.push({ref:n.ref||n.id||n.nodeId, name:n.name, role:n.role});
    (n.children||[]).forEach(c=>collect(c,acc));
    return acc;
  };
  return { matches: collect(nodes), size: flat.length };
}

