export default async (ctx, client) => {
  const ex = (op, input) => client.operations.execute({ connection_id: 432, operation_key: op, input });
  const tab_id = 558570442;
  await ex('focus_tab', { tab_id });
  await ctx.sleep(1200);
  let t = (await ex('get_accessibility_tree', { tab_id, filter: 'all' })).output;
  const composer = t.tree.find(n => (n.name||'').trim().toLowerCase() === 'message');
  await ex('click_ref', { tab_id, ref: { ref_id: composer.ref_id, document_epoch: t.document_epoch } });
  await ex('type_ref', { tab_id, ref: { ref_id: composer.ref_id, document_epoch: t.document_epoch }, text: 'GEMTEST which model are you running on right now' });
  await ctx.sleep(1800);
  t = (await ex('get_accessibility_tree', { tab_id, filter: 'all' })).output;
  const send = t.tree.find(n => (n.name||'').trim().toLowerCase() === 'send message');
  if (!send) return { error: 'no send button' };
  await ex('click_ref', { tab_id, ref: { ref_id: send.ref_id, document_epoch: t.document_epoch } });
  await ctx.sleep(2500);
  const v = await ex('evaluate', { tab_id, await_promise: true, expression: `(async()=>({ composer:(document.querySelector('#editable-message-text')||{}).innerText, items:[...document.querySelectorAll('.message-list-item')].map(m=>m.innerText.replace(/\\n+/g,' | ').slice(0,70)).slice(-3) }))()` });
  return v.output.value;
}

