/**
 * Regression: `setIfNotExists` must treat an EXPIRED row as absent.
 *
 * The Chat SDK uses this primitive for inbound message dedupe
 * (`dedupe:<platform>:<chatId>:<messageId>`, 5-minute TTL) and Lobu uses it for
 * `claimThreadBackfill` (24-hour TTL, documented as "at most once per thread PER
 * TTL WINDOW"). Both are TTL-bounded claims: once the TTL lapses the key must be
 * re-acquirable.
 *
 * The original implementation used a bare `ON CONFLICT DO NOTHING`, which has no
 * notion of expiry — a physically-present but long-expired row returned zero rows
 * and the caller read that as "already claimed". Expired rows are only swept
 * opportunistically inside `get()`, which this primitive never calls, so a key
 * stayed poisoned FOREVER.
 *
 * Prod impact (2026-07-29): Telegram message ids restart at 1 for each new bot's
 * private chat, so a new bot replayed ids a previous bot had already burned in
 * May. Every replayed id was read as a duplicate and the user's message was
 * silently dropped with a 200.
 *
 * Runs against real Postgres: the defect lives in the SQL's conflict semantics,
 * so an in-memory fake cannot reproduce it.
 */
import { afterAll, describe, expect, test } from "bun:test";
import { createConnectedGatewayStateAdapter } from "../state-adapter.js";

const hasDb = Boolean(process.env.DATABASE_URL);

/** Unique per run so repeated local runs don't collide on leftover rows. */
const suffix = `${process.pid}-${Date.now()}`;
const key = (name: string) => `test:expiry-reclaim:${name}:${suffix}`;

const adapters: Array<{ disconnect(): Promise<void> }> = [];
async function connect() {
  const adapter = await createConnectedGatewayStateAdapter();
  adapters.push(adapter);
  return adapter;
}

afterAll(async () => {
  for (const adapter of adapters) await adapter.disconnect();
});

describe("LobuStateAdapter.setIfNotExists expiry semantics", () => {
  test.skipIf(!hasDb)("reclaims a key whose row has EXPIRED", async () => {
    const adapter = await connect();
    const k = key("expired");

    // A row that is physically present but already past its TTL. A negative
    // ttlMs stamps expires_at in the past — the same state a real 5-minute
    // dedupe key reaches five minutes later.
    await adapter.set(k, "stale", -1000);
    expect(await adapter.get(k)).toBeNull(); // logically absent to readers

    // …so the claim must succeed. Before the fix this returned false and the
    // caller (SDK dedupe) discarded the inbound message.
    expect(await adapter.setIfNotExists(k, "fresh", 60_000)).toBe(true);
    expect(await adapter.get(k)).toBe("fresh");
  });

  test.skipIf(!hasDb)("still blocks while the row is LIVE", async () => {
    const adapter = await connect();
    const k = key("live");

    expect(await adapter.setIfNotExists(k, "first", 60_000)).toBe(true);
    // Second claim inside the TTL window is a genuine duplicate — the dedupe
    // guarantee the Chat SDK depends on for webhook redeliveries.
    expect(await adapter.setIfNotExists(k, "second", 60_000)).toBe(false);
    expect(await adapter.get(k)).toBe("first"); // value must NOT be overwritten
  });

  test.skipIf(!hasDb)("never reclaims a row with no expiry", async () => {
    const adapter = await connect();
    const k = key("no-ttl");

    // ttlMs omitted ⇒ expires_at IS NULL ⇒ "never expires". Reclaiming these
    // would turn a permanent marker into a renewable one.
    await adapter.set(k, "permanent");
    expect(await adapter.setIfNotExists(k, "usurper", 60_000)).toBe(false);
    expect(await adapter.get(k)).toBe("permanent");
  });

  test.skipIf(!hasDb)(
    "an expired claim is reclaimable repeatedly, not just once",
    async () => {
      const adapter = await connect();
      const k = key("repeat");

      await adapter.set(k, "gen1", -1000);
      expect(await adapter.setIfNotExists(k, "gen2", -1000)).toBe(true);
      // gen2 was itself written already-expired, so the next claim must win too.
      expect(await adapter.setIfNotExists(k, "gen3", 60_000)).toBe(true);
      expect(await adapter.get(k)).toBe("gen3");
    },
  );
});

