60	    if (this.connected) return;
61	    if (!this.connectPromise) {
62	      this.connectPromise = (async () => {
63	        try {
64	          await this.sql`SELECT 1`;
65	          this.connected = true;
66	        } catch (error) {
67	          this.connectPromise = null;
