72	    }
73	    await this.connectPromise;
74	  }
75	
76	  async disconnect(): Promise<void> {
77	    // The pool is shared with the rest of the app; we don't own its
78	    // lifecycle. Just flip the flag so subsequent calls re-run schema
79	    // checks if `connect()` is invoked again.
80	    this.connected = false;
