/**
 * The production shape, end to end: the REAL Chat SDK inbound path over the REAL
 * Postgres adapter.
 *
 * The SDK claims `dedupe:<platform>:<chatId>:<messageId>` inside
 * `handleIncomingMessage` and discards the message when the claim fails. Telegram
 * message ids restart at 1 for every new bot's private chat, so a second bot
 * replays ids the first already burned — and those rows outlive their 5-minute
 * TTL indefinitely. Pre-fix, the replayed id was read as a duplicate and the
 * message never reached any handler.
 */
describe("Chat SDK inbound dedupe over the Postgres adapter", () => {
  /** Minimal persisting adapter implementing the inbound surface under test. */
  function createAdapter() {
    return {
      name: "test",
      userName: "lobubot",
      botUserId: "999",
      async initialize() {},
      async shutdown() {},
      isDM: () => true,
      channelIdFromThreadId: (threadId: string) => threadId,
      getChannelVisibility: () => "private" as const,
      async postMessage() {
        return {} as Record<string, unknown>;
      },
      parseMessage: (raw: unknown) => raw,
    };
  }

  function createMessage(id: string, text: string) {
    return {
      id,
      text,
      author: {
        userId: "42",
        userName: "human",
        fullName: "Human",
        isBot: false,
        isMe: false,
      },
      isMention: false,
      metadata: {},
      toJSON: () => ({ id, text, raw: null }),
    };
  }

  test.skipIf(!hasDb)(
    "a stale dedupe row no longer swallows a replayed message id",
    async () => {
      const state = await connect();
      const messageId = `mid-${suffix}`;
      const threadId = `test:dm-${suffix}`;
      const delivered: string[] = [];

      const adapter = createAdapter();
      const chat = new Chat({
        userName: "lobubot",
        adapters: { test: adapter as never },
        state: state as never,
        logger: "silent",
      });
      chat.onDirectMessage(async (_t: unknown, m: { text: string }) => {
        delivered.push(m.text);
      });
      await chat.initialize();

      const dispatch = async (text: string) => {
        let processing: Promise<void> | undefined;
        (
          chat as unknown as {
            processMessage: (
              a: unknown,
              t: string,
              m: unknown,
              o: { waitUntil(task: Promise<void>): void },
            ) => void;
          }
        ).processMessage(adapter, threadId, createMessage(messageId, text), {
          waitUntil(task) {
            processing = task;
          },
        });
        if (!processing) throw new Error("SDK registered no background task");
        await processing;
      };

      // 1. First delivery claims the dedupe key and reaches the handler.
      await dispatch("first");
      expect(delivered).toEqual(["first"]);

      // 2. A genuine redelivery INSIDE the TTL window is still suppressed —
      //    the guarantee the SDK relies on for webhook retries. If the fix had
      //    weakened dedupe, this would append a duplicate.
      await dispatch("redelivery");
      expect(delivered).toEqual(["first"]);

      // 3. Age the claim past its TTL, exactly as five real minutes would.
      const sql = getDb();
      await sql`
        UPDATE chat_state_cache
        SET expires_at = now() - interval '1 hour'
        WHERE cache_key LIKE ${`dedupe:%${messageId}`}
      `;

      // 4. A new message reusing that id must now be delivered, not swallowed.
      await dispatch("after expiry");
      expect(delivered).toEqual(["first", "after expiry"]);

      await sql`DELETE FROM chat_state_cache WHERE cache_key LIKE ${`dedupe:%${messageId}`}`;
    },
  );
});

