import { describe, expect, test } from "bun:test";
import { ProviderRegistryService } from "../../services/provider-registry-service.js";
import { ApiKeyProviderModule } from "../../modules/api-key-provider-module.js";
import { moduleRegistry } from "../../modules/module-system.js";
import { ProviderCatalogService } from "../provider-catalog.js";

/**
 * PROBE (delete after): reproduce prod's provider resolution for org `buremba`
 * using the REAL config/providers.json and prod-shaped inference_providers rows.
 * Question: why did `gemini/gemini-2.5-pro` route to provider `openai`?
 */
describe("PROBE gemini resolution", () => {
  test("prod-shaped resolution", async () => {
    const registry = new ProviderRegistryService(
      `${process.cwd()}/../../config/providers.json`
    );
    const configs = await registry.getProviderConfigs();
    console.log("CONFIG PROVIDER IDS:", Object.keys(configs).join(","));

    for (const [id, entry] of Object.entries(configs)) {
      moduleRegistry.register(
        new ApiKeyProviderModule({
          providerId: id,
          providerDisplayName: entry.displayName,
          providerIconUrl: entry.iconUrl,
          envVarName: entry.envVarName,
          slug: id,
          upstreamBaseUrl: entry.upstreamBaseUrl,
          sdkCompat: entry.sdkCompat,
          defaultModel: entry.defaultModel,
          apiKeyInstructions: entry.apiKeyInstructions,
          apiKeyPlaceholder: entry.apiKeyPlaceholder,
          authProfilesManager: undefined as never,
        })
      );
    }

    // prod org `buremba` rows, verbatim shape
    const orgRows = [
      { id: 6, slug: "z-ai", kind: "z-ai", capabilities: { text: { model: "glm-5.2" } }, isDefault: false, status: "active", displayName: "z-ai", hasCustomUpstream: false },
      { id: 8, slug: "openai", kind: "openai", capabilities: { text: { model: "gpt-4o-mini" } }, isDefault: true, status: "active", displayName: "openai", hasCustomUpstream: false },
      { id: 13, slug: "gemini", kind: "gemini", capabilities: { text: { model: "gemini-2.5-pro", base_url: "https://generativelanguage.googleapis.com/v1beta/openai" } }, isDefault: true, status: "active", displayName: "gemini", hasCustomUpstream: true },
    ];

    const models = [
      "gemini/gemini-2.5-pro",
      "openai/gpt-4o-mini",
      "openrouter/anthropic/claude-sonnet-5",
      "z-ai/glm-5.2",
    ];

    const catalog = new ProviderCatalogService(
      { getAgentSettings: async () => ({ models, organizationId: "org-1" }) } as never,
      undefined as never,
      async () => orgRows as never,
      () => {}
    );

    const policy = await catalog.getModelPolicy("agent-1", "org-1");
    console.log("MODULES:", policy.modules.map((m) => m.providerId).join(","));
    console.log("ALLOWED:", JSON.stringify(policy.allowedRefs));

    for (const ref of ["gemini/gemini-2.5-pro", "z-ai/glm-5.2"]) {
      const p = await catalog.findProviderForModel(ref, policy.modules);
      console.log(`findProviderForModel(${ref}) ->`, p?.providerId ?? "UNDEFINED");
    }

    // Routability — this is what resolveDispatchModel gates on.
    for (const m of policy.modules) {
      let hasCreds = false;
      try {
        hasCreds = await m.hasCredentials("agent-1", { organizationId: "org-1" });
      } catch (e) {
        hasCreds = `THREW: ${(e as Error).message}` as never;
      }
      console.log(
        `ROUTABLE? ${m.providerId}: systemKey=${m.hasSystemKey()} hasCredentials=${hasCreds}`
      );
    }
    expect(true).toBe(true);
  });
});

