const createdBy = c.get("user")?.id ?? null;

// Seed the catalog's default text model when the caller named none.
//
// A row with NO `capabilities.text` block is invisible to
// `resolveInferenceProviderConfig` — it selects `capabilities -> <modality>`
// and returns null when the block is absent (provider-secrets.ts), so
// `resolveUrlInvariant` reports `no-custom-upstream` and the row's own org
// key is never read. For a catalog provider with no deployment env key that
// resolves to NO credential at all: the module is dropped from routing, the
// dispatcher's credentialed-fallback scan picks some other provider, and the
// model goes upstream with its prefix intact — surfacing as an opaque
// "400 invalid model ID" that names neither the real provider nor the cause.
//
// Such a row is born permanently unroutable, so seed it here rather than
// letting each caller (CLI, UI, SDK) remember to pass `--model`.
const requestedCapabilities =
	(body.capabilities as InferenceCapabilities) ?? {};
const hasTextModel = !!requestedCapabilities.text?.model?.trim();
const capabilities =
	hasTextModel || !catalogEntry?.defaultModel
		? requestedCapabilities
		: {
				...requestedCapabilities,
				text: {
					...requestedCapabilities.text,
					model: catalogEntry.defaultModel,
				},
			};
if (!hasTextModel && !catalogEntry?.defaultModel) {
	// Unknown kind (custom endpoint) or a catalog entry with no default: we
	// cannot seed one. Say so — the row will not route until a model is set.
	logger.warn(
		{ slug, kind },
		"[inference-providers POST] created without a text model and no catalog default to seed — the provider will not route until `capabilities.text.model` is set"
	);
}

const result = await createInferenceProvider({
	organizationId: orgId,
	slug,
	kind,
	displayName: typeof body.displayName === "string" ? body.displayName : null,
	apiKey,
	capabilities,
	createdBy,
});

