export default async (ctx, client) => {
  const out = {};
  for (const model of ["openai/gpt-4o-mini", "z-ai/glm-5.2", "gemini/gemini-2.5-pro"]) {
    try {
      const res = await client.conversations.send({
        agent_id: "personal-agent",
        text: "Reply with exactly: OK",
        model,
        wait: true,
        timeout_ms: 45000,
      });
      out[model] = { status: res?.status, reply: String(res?.reply ?? "").slice(0, 60) };
    } catch (e) {
      out[model] = { error: String(e?.message ?? e).slice(0, 200) };
    }
  }
  return out;
};

