const requestedCapabilities =
	(body.capabilities as InferenceCapabilities) ?? {};
const hasTextModel = !!requestedCapabilities.text?.model?.trim();

// Only seed a row that will ACTUALLY route, because a text model is also the
// predicate `promoteOldestRunnableProvider` uses to pick the org default —
// seeding an unroutable row would promote it to default and break every
// allow-all agent in the org.
//
// `getModelPolicy` keys its module map by the row's SLUG. So the row routes
// only when either:
//   - slug === kind      → the catalog's own static module answers to it, or
//   - a text base_url    → `synthesizeOrgProviderModule` can build a module.
// An alias slug with no base_url (slug=my-gemini, kind=gemini) matches
// neither and is dropped by the policy, so it must NOT look configured.
const hasTextBaseUrl = !!requestedCapabilities.text?.base_url?.trim();
const wouldRoute = slug === kind || hasTextBaseUrl;
const capabilities =
	hasTextModel || !catalogDefaultModel || !wouldRoute
		? requestedCapabilities
		: {
				...requestedCapabilities,
				text: {
					...requestedCapabilities.text,
					model: catalogDefaultModel,
				},
			};
if (!hasTextModel && !capabilities.text?.model) {
	// Nothing seeded: unknown kind, no catalog default, or an alias slug with
	// no upstream to route to. Say so at creation — otherwise the row's only
	// symptom is a far-away, differently-worded 400.
	logger.warn(
		{ slug, kind, wouldRoute },
		"[inference-providers POST] created with no text model — this provider will not route until `capabilities.text.model` is set (an alias slug also needs `capabilities.text.base_url`)"
	);
}

