export default async (ctx, client) => {
  const conns = await client.connections.list();
  const raw = JSON.stringify(conns);
  return { conns: raw.slice(0, 1800) };
};

export default async (ctx, client) => {
  const conns = await client.connections.list();
  const list = conns.connections || [];
  return {
    browsery: list
      .filter((c) => /browser|owletto|chrome/i.test(c.connector_key + " " + (c.display_name || "")))
      .map((c) => ({ id: c.id, key: c.connector_key, name: c.display_name, status: c.status, online: c.device_online })),
    all_keys: list.map((c) => c.connector_key),
  };
};

export default async (ctx, client) => {
  const ops = await client.operations.listAvailable({ connection_id: 432 });
  const raw = JSON.stringify(ops);
  return { ops: raw.slice(0, 1600) };
};

export default async (ctx, client) => {
  const ops = await client.operations.listAvailable({ connection_id: 432 });
  return { keys: (ops.operations || []).map((o) => o.operation_key) };
};

